// Real pinned Pyodide/NumPy benchmark, with a fresh process per source version.
// Dev tooling uses the repository's installed web/node_modules/pyodide runtime.
import fs from 'node:fs';
import path from 'node:path';
import {parseArgs} from 'node:util';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';

const here = path.dirname(fileURLToPath(import.meta.url));
const {values} = parseArgs({options: {
  source: {type:'string', default:path.resolve(here, '../src/paperleet_torch')},
  runtime: {type:'string', default:path.resolve(here, '../../../web/node_modules/pyodide')},
  cache: {type:'string', default:path.resolve(here, '../../../web/public/browser-runtime/pyodide-0.29.4')},
  output: {type:'string'}, repeat: {type:'string', default:'11'}, iterations: {type:'string', default:'30'},
  benchmark: {type:'string', default:'runtime'},
  dtype: {type:'string', default:'float32'}, case: {type:'string', multiple:true},
}});
const repeat = Number(values.repeat), iterations = Number(values.iterations);
if (!Number.isInteger(repeat) || !Number.isInteger(iterations) || Math.min(repeat,iterations) < 1) {
  throw new Error('repeat and iterations must be positive integers');
}
if (!['runtime','schedulers','nn','module_hooks','tensor_hooks','tensor_factories','arithmetic','selection'].includes(values.benchmark)) throw new Error('Unknown benchmark');
if (values.benchmark === 'schedulers' && (values.case || values.dtype !== 'float32')) {
  throw new Error('Scheduler suite uses fixed float32 fixtures and all cases');
}
const {loadPyodide} = await import(pathToFileURL(path.join(path.resolve(values.runtime), 'pyodide.mjs')).href);
const py = await loadPyodide({indexURL:path.resolve(values.runtime), packageCacheDir:path.resolve(values.cache),
  stdout(){}, stderr(){}});
await py.loadPackage('numpy');
py.FS.mkdirTree('/runtime/paperleet_torch');
const sourceHashes = {};
const resourceHashes = {};
for (const name of fs.readdirSync(values.source).filter(name => name.endsWith('.py') || ['LICENSE','NOTICE'].includes(name))) {
  const raw = fs.readFileSync(path.join(values.source,name));
  (name.endsWith('.py') ? sourceHashes : resourceHashes)[name] = createHash('sha256').update(raw).digest('hex');
  py.FS.writeFile('/runtime/paperleet_torch/'+name, raw.toString('utf8'));
}
py.runPython('import sys\nsys.path.insert(0,"/runtime")');
py.FS.writeFile('/runtime/bench_runtime.py',fs.readFileSync(path.join(here,`bench_${values.benchmark}.py`),'utf8'));
const options = values.benchmark === 'schedulers' ? {repeat,iterations} : {repeat,iterations,dtype:values.dtype,cases:values.case};
py.globals.set('benchmark_options_json',JSON.stringify(options));
const report = JSON.parse(py.runPython('import json, bench_runtime\njson.dumps(bench_runtime.run_benchmarks(**json.loads(benchmark_options_json)))'));
report.pyodide = py.version;
report.source = path.resolve(values.source);
report.source_hashes = sourceHashes;
report.resource_hashes = resourceHashes;
const output = JSON.stringify(report,null,2)+'\n';
if (values.output) fs.writeFileSync(values.output,output);
process.stdout.write(output);

harness_sources.bench_tensor_hooks.py:
"""Tensor callback dispatch, retention and registration costs on CPU/Pyodide."""
import argparse
import json
import platform
import statistics
import sys
import time

import numpy as np
import paperleet_torch
from paperleet_torch import torch


def run_benchmarks(repeat=11, iterations=1200, warmup=3, dtype='float32', cases=None):
    if dtype not in ('float32', 'float64') or min(repeat, iterations) < 1 or warmup < 0:
        raise ValueError('Use float32/float64 and positive sample counts')
    kind = getattr(torch, dtype)
    def leaf_case(hook=None, post=None):
        value = torch.ones(16, dtype=kind, requires_grad=True)
        seed = torch.ones_like(value)
        if hook is not None: value.register_hook(hook)
        if post is not None: value.register_post_accumulate_grad_hook(post)
        def run():
            value.grad = None
            value.backward(seed)
        return run
    def graph_case(retain=False, hook=None):
        x = torch.ones(16, 32, dtype=kind, requires_grad=True)
        def run():
            x.grad = None
            middle = x.square()
            if retain: middle.retain_grad()
            if hook is not None: middle.register_hook(hook)
            middle.square().mean().backward()
        return run
    available = {
        'leaf_backward': leaf_case(),
        'graph_backward': graph_case(),
        'retained_backward': graph_case(retain=True),
    }
    if hasattr(torch.Tensor, 'register_hook'):
        unchanged = lambda gradient: None
        available.update({
            'leaf_observer': leaf_case(hook=unchanged),
            'leaf_transform': leaf_case(hook=lambda gradient: gradient * .5),
            'leaf_post_accumulate': leaf_case(post=lambda parameter: None),
            'leaf_pre_post': leaf_case(hook=unchanged, post=lambda parameter: None),
            'graph_intermediate_observer': graph_case(hook=unchanged),
            'graph_retained_observer': graph_case(retain=True, hook=unchanged),
        })
        temporary = torch.tensor(2., dtype=kind, requires_grad=True)
        def register_remove(): temporary.register_hook(unchanged).remove()
        available['register_remove'] = register_remove
    if hasattr(torch.Tensor, 'copy_'):
        source = torch.ones(64, 128, dtype=kind)
        destination = torch.zeros_like(source)
        strided = torch.zeros(128, 64, dtype=kind).T
        available['copy_contiguous'] = lambda: destination.copy_(source)
        available['copy_strided'] = lambda: strided.copy_(source)
    selected = list(available) if cases is None else list(cases)
    if not selected or len(set(selected)) != len(selected) or any(name not in available for name in selected):
        raise ValueError('Select unique available cases: ' + ', '.join(available))
    results = {}
    for name in selected:
        run = available[name]
        inner = iterations * (10 if name == 'register_remove' else 1)
        for _ in range(warmup): run()
        samples = []
        for _ in range(repeat):
            start = time.perf_counter()
            for _ in range(inner): run()
            samples.append((time.perf_counter() - start) * 1000 / inner)
        results[name] = dict(median_ms=statistics.median(samples), samples_ms=samples, iterations=inner)
    return dict(library_version=paperleet_torch.__version__, python=platform.python_version(),
                numpy=np.__version__, platform=platform.platform(), dtype=dtype,
                implementation=sys.modules[torch.Tensor.__module__].__file__,
                repeat=repeat, iterations=iterations, warmup=warmup, results=results)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repeat', type=int, default=11)
    parser.add_argument('--iterations', type=int, default=1200)
    parser.add_argument('--dtype', choices=['float32', 'float64'], default='float32')
    parser.add_argument('--case', action='append', dest='cases')
    parser.add_argument('--output')
    options = parser.parse_args()
    report = json.dumps(run_benchmarks(options.repeat, options.iterations, dtype=options.dtype, cases=options.cases), indent=2) + '\n'
    if options.output:
        with open(options.output, 'w', encoding='utf8') as stream: stream.write(report)
    print(report)

harness_sources.bench_schedulers.py:
"""Scheduler-only and complete scheduled-training costs on CPU or Pyodide.

Scheduler-only fixtures perform one optimizer step before warmup; timed calls
measure scheduler.step(), not optimizer work. No gradients are attached there.
The MLP cases include zeroing, forward, backward and SGD, with/without scheduling.
Fixtures, imports and result serialization are excluded; no CI timing thresholds.
"""
import argparse
import json
import platform
import statistics
import sys
import time

import numpy as np


def workloads(api):
    S = api.optim.lr_scheduler
    def optimizer(groups=8, tensor_lr=False):
        return api.optim.SGD([{'params':[api.nn.Parameter(api.ones(1))],
                              'lr':api.tensor(.1/(index+1)) if tensor_lr else .1/(index+1)}
                             for index in range(groups)])
    available = {}
    for name, count, tensor, factory in (
        ('step_one_group',1,False,lambda o:S.StepLR(o,200,.9)),
        ('step_eight_groups',8,False,lambda o:S.StepLR(o,200,.9)),
        ('cosine_eight_groups',8,False,lambda o:S.CosineAnnealingLR(o,1000,1e-5)),
        ('tensor_cosine_eight_groups',8,True,lambda o:S.CosineAnnealingLR(o,1000,1e-5)),
        ('warmup_cosine_eight_groups',8,False,
         lambda o:S.SequentialLR(o,[S.LinearLR(o,.2,total_iters=5),S.CosineAnnealingLR(o,1000,1e-5)],[5])),
        ('plateau_eight_groups',8,False,lambda o:S.ReduceLROnPlateau(o,patience=5,min_lr=1e-5)),
    ):
        o = optimizer(count,tensor);s = factory(o);o.step()
        available[name] = (lambda s=s:s.step(1.)) if name.startswith('plateau') else s.step
    for scheduled in (False,True):
        api.manual_seed(412)
        model = api.nn.Sequential(api.nn.Linear(16,32),api.nn.ReLU(),api.nn.Linear(32,8))
        o = api.optim.SGD(model.parameters(),lr=.001)
        s = S.StepLR(o,200,.9) if scheduled else None
        x = api.ones(16,16)
        def train(model=model,o=o,s=s,x=x):
            o.zero_grad();model(x).square().mean().backward();o.step()
            if s is not None:s.step()
        available['scheduled_mlp' if scheduled else 'plain_mlp'] = train
    return available


def run_benchmarks(*, backend='lite', repeat=11, iterations=120, warmup=3):
    if repeat < 1 or iterations < 1 or warmup < 0:
        raise ValueError('Positive repeat/iterations and nonnegative warmup required')
    if backend == 'lite':
        from paperleet_torch import torch as api, __version__ as version
    elif backend == 'native':
        import torch as api
        version = api.__version__
        if getattr(api,'_browser_capabilities',None) is not None:
            raise ValueError('Native comparison must not use torch aliases')
    else:raise ValueError('Unknown backend')
    results = {}
    for name, operation in workloads(api).items():
        for _ in range(warmup):operation()
        samples = []
        for _ in range(repeat):
            start = time.perf_counter()
            for _ in range(iterations):operation()
            samples.append((time.perf_counter()-start)*1000/iterations)
        results[name] = {'median_ms':statistics.median(samples),'samples_ms':samples}
    return dict(backend=backend,version=version,python=platform.python_version(),numpy=np.__version__,
                platform=platform.platform(),implementation=sys.modules[api.Tensor.__module__].__file__,
                repeat=repeat,iterations=iterations,warmup=warmup,dtype='float32',seed=412,results=results)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--backend',choices=['lite','native'],default='lite')
    parser.add_argument('--output')
    parser.add_argument('--repeat',type=int,default=11)
    parser.add_argument('--iterations',type=int,default=120)
    options = parser.parse_args()
    report = json.dumps(run_benchmarks(backend=options.backend,repeat=options.repeat,
                                     iterations=options.iterations),indent=2)+'\n'
    if options.output:
        with open(options.output,'w',encoding='utf8') as stream:stream.write(report)
    print(report)

harness_sources.bench_nn.py:
"""Normalization, embedding, activation and complete encoder CPU/WASM workloads.

Existing functional workloads also run against pre-module source snapshots.
New-layer cases are included only when those classes are present in the API.
Imports/fixtures are excluded; each backward call resets the relevant gradients.
"""
import argparse
import json
import platform
import statistics
import sys
import time

import numpy as np
from paperleet_torch import __version__,torch


def workloads(dtype='float32'):
    dtype=np.dtype(dtype)
    if dtype not in (np.dtype('float32'),np.dtype('float64')):raise ValueError('Use float32/float64')
    rng=np.random.default_rng(193)
    def tensor(shape,grad=True):
        return torch.tensor(rng.normal(size=shape).astype(dtype),requires_grad=grad)
    available={}
    for name,kind,input_grad,weight_grad,bias_grad in (
        ('layer_norm_backward','layer',True,True,True),
        ('rms_norm_backward','rms',True,True,False),
        ('layer_norm_affine_only','layer',False,True,True),
        ('rms_norm_weight_only','rms',False,True,False),
        ('layer_norm_bias_only','layer',False,False,True),
    ):
        x=tensor((16,32,128),input_grad);w=tensor((128,),weight_grad)
        b=tensor((128,),bias_grad) if kind=='layer' else None
        def run(x=x,w=w,b=b,kind=kind):
            for value in (x,w,b):
                if value is not None:value.grad=None
            output=(torch.nn.functional.layer_norm(x,(128,),w,b,1e-5) if kind=='layer'
                    else torch.nn.functional.rms_norm(x,(128,),w,1e-5))
            output.square().mean().backward()
        available[name]=run
    weights=tensor((256,32));ids=torch.tensor(rng.integers(0,256,size=(16,32)),dtype=torch.int64)
    def embedding_backward():
        weights.grad=None
        torch.nn.functional.embedding(ids,weights,padding_idx=0,scale_grad_by_freq=True).square().mean().backward()
    available['embedding_backward']=embedding_backward
    if 'GELU' not in vars(torch.nn):return available
    for approximate in ('none','tanh'):
        x=tensor((64,128));layer=torch.nn.GELU(approximate)
        def activation(x=x,layer=layer):
            x.grad=None;layer(x).square().mean().backward()
        available['gelu_'+approximate+'_backward']=activation
    dropped=tensor((64,128));dropout=torch.nn.Dropout(.1)
    def dropout_backward():
        dropped.grad=None;dropout(dropped).square().mean().backward()
    available['dropout_backward']=dropout_backward
    class Encoder(torch.nn.Module):
        def __init__(self):
            super().__init__();N=torch.nn;options={'dtype':dtype}
            self.embed=N.Embedding(128,32,padding_idx=0,**options)
            self.norm=N.LayerNorm(32,**options);self.qkv=N.Linear(32,96,**options)
            self.rms=N.RMSNorm(32,eps=1e-5,**options)
            self.ff=N.Sequential(N.Linear(32,64,**options),N.GELU('tanh'),N.Dropout(.1),N.Linear(64,32,**options))
            self.head=N.Linear(32,5,**options)
        def forward(self,indices):
            x=self.embed(indices);batch,length=indices.shape
            q,k,v=self.qkv(self.norm(x)).reshape(batch,length,3,4,8).permute(2,0,3,1,4)
            attention=torch.nn.functional.scaled_dot_product_attention(q,k,v,is_causal=True)
            x=x+attention.transpose(1,2).reshape(batch,length,32)
            return self.head((x+self.ff(self.rms(x))).mean(1))
    torch.manual_seed(193);model=Encoder();optimizer=torch.optim.SGD(model.parameters(),lr=.001,momentum=.8)
    indices=torch.tensor(rng.integers(0,128,size=(8,16)),dtype=torch.int64)
    labels=torch.tensor(np.arange(8)%5,dtype=torch.int64);loss=torch.nn.CrossEntropyLoss()
    def encoder_training_step():
        optimizer.zero_grad();loss(model(indices),labels).backward();optimizer.step()
    available['encoder_training_step']=encoder_training_step
    return available


def run_benchmarks(*,repeat=11,iterations=120,warmup=3,dtype='float32',cases=None):
    if repeat<1 or iterations<1 or warmup<0:raise ValueError('Invalid sampling configuration')
    available=workloads(dtype);names=list(available) if cases is None else list(cases)
    if not names or len(set(names))!=len(names) or any(n not in available for n in names):
        raise ValueError('Select unique available cases: '+', '.join(available))
    results={}
    for name in names:
        operation=available[name]
        for _ in range(warmup):operation()
        samples=[]
        for _ in range(repeat):
            start=time.perf_counter()
            for _ in range(iterations):operation()
            samples.append((time.perf_counter()-start)*1000/iterations)
        results[name]={'median_ms':statistics.median(samples),'samples_ms':samples}
    return dict(library_version=__version__,python=platform.python_version(),numpy=np.__version__,
                platform=platform.platform(),implementation=sys.modules[torch.Tensor.__module__].__file__,
                dtype=np.dtype(dtype).name,seed=193,repeat=repeat,iterations=iterations,warmup=warmup,results=results)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output');parser.add_argument('--repeat',type=int,default=11)
    parser.add_argument('--iterations',type=int,default=120)
    parser.add_argument('--dtype',choices=['float32','float64'],default='float32')
    parser.add_argument('--case',action='append',dest='cases')
    options=parser.parse_args()
    report=json.dumps(run_benchmarks(repeat=options.repeat,iterations=options.iterations,
                                    dtype=options.dtype,cases=options.cases),indent=2)+'\n'
    if options.output:
        with open(options.output,'w',encoding='utf8') as stream:stream.write(report)
    print(report)

